# Generated by build.py from recipe.yml for recipe mqtt-test-a-sensor-to-alert-flow. Do not edit.
set -e
cd "$(dirname "$0")"
cat > alert.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The service: mails ops@example.com when a sensor's temperature is past the limit.
# Usage: sh alert.sh <mqtt port> <smtp port> <sensor> <limit>
topic=sensors/$3/temp
reading=""
for try in 1 2 3 4 5; do
  # A subscriber is sent the topic's length in two bytes, the topic, then the payload.
  reading=$(curl -s -m 5 "mqtt://127.0.0.1:$1/$topic" | tail -c +$(( ${#topic} + 3 )))
  [ -n "$reading" ] && break
  sleep 1
done
if [ -z "$reading" ]; then
  echo "no reading from $3"
  exit 1
fi
if awk -v r="$reading" -v l="$4" 'BEGIN { exit !(r + 0 > l + 0) }'; then
  printf 'From: sensors@example.com\r\nTo: ops@example.com\r\nSubject: %s at %s C\r\n\r\n%s reads %s C, past the limit of %s C.\r\n' \
    "$3" "$reading" "$3" "$reading" "$4" > alert.eml
  curl -sS --mail-from sensors@example.com --mail-rcpt ops@example.com -T alert.eml "smtp://127.0.0.1:$2/" || exit 1
  echo "alert sent for $3 at $reading"
else
  echo "no alert for $3 at $reading"
fi
EOF
surl --allow-anonymous --topic "sensors/#;retain" mqtt://127.0.0.1:8080/ smtp://127.0.0.1:8081/ pop3://127.0.0.1:8082/ &
sleep 1
curl -s -d 81.5 mqtt://127.0.0.1:8080/sensors/boiler/temp && sh alert.sh 8080 8081 boiler 75
kill $(jobs -p)
